package com.gamezone.darumabash.gwt;

import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.graphics.Color;
import com.badlogic.gdx.graphics.g2d.BitmapFont;
import com.gamezone.darumabash.Platform;

/**
 * Browser implementation of {@link Platform}.
 *
 * <p>The desktop build rasterises Baloo 2 ExtraBold from the TTF at startup; the GWT backend has no
 * FreeType, so it loads pre-baked AngelCode atlases instead. Those atlases are generated by
 * {@code tools/bake-web-fonts.py} with exactly the sizes, outline widths, shadow offsets and colours
 * the desktop build uses, which is why this class only has to pick a file per size.
 *
 * <p>Screenshots are a desktop-only debugging aid ({@code --shot=}), so the browser ignores them.
 */
final class WebPlatform implements Platform.Impl {

    private static final String TITLE = "fonts/daruma-title.fnt";
    private static final String BODY = "fonts/daruma-body.fnt";
    private static final String SMALL = "fonts/daruma-small.fnt";

    @Override
    public BitmapFont createFont(int size, float border, int shadow, Color text, Color outline) {
        String path = size >= 60 ? TITLE : size >= 26 ? BODY : SMALL;
        // Standard AngelCode atlas (y-down), so the one-argument constructor's default flip applies.
        // The atlas already carries the desktop palette and outline, so no tint is needed.
        return new BitmapFont(Gdx.files.internal(path));
    }

    @Override
    public void captureScreenshot(String path) {
        Gdx.app.log("WebPlatform", "screenshots are desktop-only; ignoring " + path);
    }
}
